import { gs, GlideRecord } from '@servicenow/glide';
import { T, me, isReviewer } from './auth';
import { badRequest, forbidden, requireSysId } from './http';
import { responseJson } from './responses';
/**
 * Reviewer raises a follow-up on a session (any state except abandoned).
 * Lands as a Response with status 'requested'; the requester's next
 * conversation picks it up via GET /followups.
 */
export function raiseFollowUp(s, input) {
    if (!isReviewer())
        throw forbidden('Only reviewers can raise follow-up questions');
    if (s.getValue('state') === 'abandoned')
        throw badRequest('Cannot raise follow-ups on an abandoned session');
    const question = (input.question || '').trim();
    if (!question)
        throw badRequest('question is required');
    const r = new GlideRecord(T.response);
    r.initialize();
    r.setValue('session', s.getUniqueValue());
    if (input.criterion_id)
        r.setValue('criterion', requireSysId(input.criterion_id, 'criterion_id'));
    r.setValue('question_asked', question.substring(0, 1000));
    r.setValue('status', 'requested');
    r.setValue('asked_by', 'assessor');
    r.setValue('asked_by_user', me());
    r.setValue('target_table', s.getValue('target_table'));
    r.setValue('target_record', s.getValue('target_record'));
    const id = r.insert();
    if (!id)
        throw badRequest('Follow-up could not be saved');
    // Hook for notifications: subscribe a Notification or Flow to this event.
    gs.eventQueue('x_312586_gintake.followup.raised', r, s.getValue('requester'), s.getValue('number'));
    return responseJson(r);
}
/** Open follow-ups addressed to the caller, across all of their sessions. */
export function myOpenFollowUps() {
    const out = [];
    const r = new GlideRecord(T.response);
    r.addQuery('status', 'requested');
    r.addQuery('session.requester', me());
    r.orderBy('sys_created_on');
    r.setLimit(100);
    r.query();
    while (r.next()) {
        out.push({
            ...responseJson(r),
            session_id: r.getValue('session'),
            session_number: r.getDisplayValue('session'),
            profile_name: r.session.profile.getDisplayValue(),
            target_table: r.getValue('target_table') || null,
            target_record: r.getValue('target_record') || null,
            raised_on: r.getValue('sys_created_on'),
        });
    }
    return out;
}
